mapper.select:
/* AppAdminApprovalMapper.selectPendingCorrOt */ SELECT R.REQ_ID AS reqId , R.REQ_TYPE AS reqType , R.USER_CD AS userCd , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'USER_NM', R.USER_CD, null) AS userNm , R.SITE_CD AS siteCd , R.NODE_CD AS nodeCd , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'NODE', R.SITE_CD, COALESCE(R.NODE_CD, U.NODE_CD)) AS nodeNm , R.WORK_YMD AS workYmd , R.WORK_SEQ AS workSeq , R.START_DATE AS startDate , R.START_TIME AS startTime , R.END_DATE AS endDate , R.END_TIME AS endTime , R.SCH_CD AS schCd
, RSE.FST_SCH_STR_TIME AS schFstStrTime , RSE.FST_SCH_END_TIME AS schFstEndTime , RSE.SEC_SCH_STR_TIME AS schSecStrTime , RSE.SEC_SCH_END_TIME AS schSecEndTime , R.REQ_REASON AS reqReason , DATE_FORMAT(R.INSERT_DATE, '%Y-%m-%dT%H:%i:%s') AS reqDate FROM TB_USER_ATTD_REQ R LEFT JOIN TB_USER U ON U.CMPNY_CD = R.CMPNY_CD AND U.USER_CD = R.USER_CD
LEFT JOIN ( ) RSE ON RSE.CMPNY_CD = R.CMPNY_CD AND RSE.SITE_CD = R.SITE_CD AND RSE.SCH_CD = R.SCH_CD AND RSE.APPLY_DATE = ( SELECT COALESCE( MAX(CASE WHEN SE.APPLY_DATE <= R.WORK_YMD THEN SE.APPLY_DATE END) , MIN(SE.APPLY_DATE) ) FROM ( ) SE WHERE SE.CMPNY_CD = R.CMPNY_CD AND SE.SITE_CD = R.SITE_CD AND SE.SCH_CD = R.SCH_CD ) WHERE 1 = 1
ORDER BY R.INSERT_DATE DESC LIMIT #{limit} OFFSET #{offset}

/* AppAdminApprovalMapper.selectPendingLeave */ SELECT AP.REQ_ID AS reqId , AP.APPROVAL_STEP AS approvalStep , R.REQ_TYPE AS reqType , R.USER_CD AS requesterUserCd , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'USER_NM', R.USER_CD, null) AS requesterUserNm , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'NODE', R.SITE_CD, R.NODE_CD) AS nodeNm , R.WORK_YMD AS workYmd , R.LEAVE_TYPE AS leaveType , U.LEAVE_CD AS leaveCd , LT.LEAVE_NO AS leaveNo , LT.LEAVE_NM AS leaveNm , U.USE_UNIT_TYPE AS useUnitType , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'SYST_VAL', U.USE_UNIT_TYPE, 'SYS025') AS unitNm , R.LEAVE_DAYS AS leaveDays , U.LEAVE_MINUTES AS leaveMinutes , R.START_TIME AS startTime , R.END_TIME AS endTime , R.REQ_REASON AS reqReason , DATE_FORMAT(R.INSERT_DATE, '%Y-%m-%dT%H:%i:%s') AS reqDate , CASE WHEN R.USER_CD = #{approverUserCd} THEN 'Y' ELSE 'N' END AS selfYn FROM TB_USER_ATTD_REQ_APPROVAL AP JOIN TB_USER_ATTD_REQ R ON R.CMPNY_CD = AP.CMPNY_CD AND R.REQ_ID = AP.REQ_ID
LEFT JOIN TB_USER_LEAVE_USE U ON U.CMPNY_CD = R.CMPNY_CD AND U.DEL_YN = 'N' AND ( (R.REQ_TYPE = '05' AND U.REQ_ID = R.REQ_ID AND U.LEAVE_STATUS = 'CONFIRMED' AND U.LEAVE_ID = ( SELECT MIN(X.LEAVE_ID) FROM TB_USER_LEAVE_USE X WHERE X.CMPNY_CD = R.CMPNY_CD AND X.REQ_ID = R.REQ_ID AND X.LEAVE_STATUS = 'CONFIRMED' AND X.DEL_YN = 'N' )) OR (R.REQ_TYPE = '06' AND U.LEAVE_ID = R.TARGET_ID) ) LEFT JOIN TB_LEAVE_TYPE_MGMT LT ON LT.CMPNY_CD = U.CMPNY_CD AND LT.LEAVE_CD = U.LEAVE_CD WHERE AP.CMPNY_CD = #{cmpnyCd} AND AP.APPROVER_USER_CD = #{approverUserCd} AND AP.APPROVAL_STATUS = '01' AND R.REQ_TYPE IN ('05', '06') AND R.REQ_STATUS = '01' AND R.DEL_YN = 'N'
AND ( R.USER_CD LIKE CONCAT('%', #{keyword}, '%') OR FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'USER_NM', R.USER_CD, null) LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY R.INSERT_DATE DESC LIMIT #{limit} OFFSET #{offset}

/* AppAdminApprovalMapper.selectNeighborAttdSegments */
SELECT
      M.WORK_YMD        AS workYmd
    , M.WORK_SEQ        AS workSeq
    , M.CHECK_IN_DATE   AS checkInDate
    , M.CHECK_IN_TIME   AS checkInTime
    , M.CHECK_OUT_DATE  AS checkOutDate
    , M.CHECK_OUT_TIME  AS checkOutTime
  FROM TB_USER_ATTD_MGMT M
 WHERE M.CMPNY_CD = #{cmpnyCd}
   AND M.SITE_CD  = #{siteCd}
   AND M.USER_CD  = #{userCd}
   AND M.WORK_YMD BETWEEN #{fromYmd} AND #{toYmd}
   AND M.WORK_YMD != #{baseYmd}
   AND M.DEL_YN   = 'N'
 ORDER BY M.WORK_YMD, M.WORK_SEQ

/* AppAdminApprovalMapper.selectLeaveBody */ SELECT U.LEAVE_CD AS leaveCd , LT.LEAVE_NO AS leaveNo , LT.LEAVE_NM AS leaveNm , U.USE_UNIT_TYPE AS useUnitType , FNC_CMM_INFO_SRCH(U.CMPNY_CD, 'SYST_VAL', U.USE_UNIT_TYPE, 'SYS025') AS unitNm
, CASE WHEN U.REQ_ID = #{reqId} THEN ( SELECT SUM(X.LEAVE_DAYS) FROM TB_USER_LEAVE_USE X WHERE X.CMPNY_CD = U.CMPNY_CD AND X.REQ_ID = U.REQ_ID AND X.LEAVE_STATUS = 'CONFIRMED' AND X.DEL_YN = 'N' ) ELSE U.LEAVE_DAYS END AS leaveDays , U.LEAVE_MINUTES AS leaveMinutes , U.START_DATE AS startDate , U.START_TIME AS startTime , U.END_DATE AS endDate , U.END_TIME AS endTime FROM TB_USER_LEAVE_USE U LEFT JOIN TB_LEAVE_TYPE_MGMT LT ON LT.CMPNY_CD = U.CMPNY_CD AND LT.LEAVE_CD = U.LEAVE_CD WHERE U.CMPNY_CD = #{cmpnyCd} AND U.DEL_YN = 'N' AND ( (U.REQ_ID = #{reqId} AND U.LEAVE_STATUS = 'CONFIRMED') OR (#{targetId} IS NOT NULL AND U.LEAVE_ID = #{targetId}) )
ORDER BY U.LEAVE_ID LIMIT 1

/* AppAdminApprovalMapper.selectLeaveBalance */
SELECT
      IFNULL(SUM(G.GRANT_DAYS), 0)                  AS granted
    , IFNULL(SUM(G.USED_DAYS), 0)                   AS used
    , IFNULL(SUM(G.GRANT_DAYS) - SUM(G.USED_DAYS), 0) AS remain
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD  = #{cmpnyCd}
   AND G.USER_CD   = #{userCd}
   AND G.LEAVE_CD  = #{leaveCd}
   AND G.STATUS    = 'ACTIVE'
   AND G.EXPIRE_YN = 'N'
   AND G.DEL_YN    = 'N'

/* AppAdminApprovalMapper.selectSchedBody */ SELECT CS.SCH_CD AS curSchCd , CS.SCH_NO AS curSchNo , CSE.FST_SCH_STR_TIME AS curFstStrTime , CSE.FST_SCH_END_TIME AS curFstEndTime , CSE.SEC_SCH_STR_TIME AS curSecStrTime , CSE.SEC_SCH_END_TIME AS curSecEndTime , TS.SCH_CD AS reqSchCd , TS.SCH_NO AS reqSchNo , TSE.FST_SCH_STR_TIME AS reqFstStrTime , TSE.FST_SCH_END_TIME AS reqFstEndTime , TSE.SEC_SCH_STR_TIME AS reqSecStrTime , TSE.SEC_SCH_END_TIME AS reqSecEndTime FROM TB_SCH_MGMT TS LEFT JOIN ( ) TSE ON TSE.CMPNY_CD = TS.CMPNY_CD AND TSE.SITE_CD = TS.SITE_CD AND TSE.SCH_CD = TS.SCH_CD
AND TSE.APPLY_DATE = ( SELECT COALESCE( MAX(CASE WHEN SE.APPLY_DATE <= #{workYmd} THEN SE.APPLY_DATE END) , MIN(SE.APPLY_DATE) ) FROM ( ) SE WHERE SE.CMPNY_CD = TS.CMPNY_CD AND SE.SITE_CD = TS.SITE_CD AND SE.SCH_CD = TS.SCH_CD ) LEFT JOIN TB_USER_WORK_PLAN WP ON WP.CMPNY_CD = #{cmpnyCd} AND WP.SITE_CD = #{siteCd} AND WP.USER_CD = #{userCd} AND WP.WORK_YMD = #{workYmd} LEFT JOIN TB_SCH_MGMT CS ON CS.CMPNY_CD = #{cmpnyCd} AND CS.SITE_CD = #{siteCd} AND CS.SCH_CD = WP.WORK_PLAN_CD LEFT JOIN ( ) CSE ON CSE.CMPNY_CD = WP.CMPNY_CD AND CSE.SITE_CD = WP.SITE_CD AND CSE.SCH_CD = WP.WORK_PLAN_CD
AND CSE.APPLY_DATE = ( SELECT COALESCE( MAX(CASE WHEN SE.APPLY_DATE <= WP.WORK_YMD THEN SE.APPLY_DATE END) , MIN(SE.APPLY_DATE) ) FROM ( ) SE WHERE SE.CMPNY_CD = WP.CMPNY_CD AND SE.SITE_CD = WP.SITE_CD AND SE.SCH_CD = WP.WORK_PLAN_CD ) WHERE TS.CMPNY_CD = #{cmpnyCd} AND TS.SITE_CD = #{siteCd} AND TS.SCH_CD = #{reqSchCd} LIMIT 1

/* AppAdminApprovalMapper.countCloseCovering */


    SELECT COUNT(*)
      FROM TB_ATTD_CLOSE C
     WHERE C.CMPNY_CD = #{cmpnyCd}
       AND C.SITE_CD  = #{siteCd}
       AND C.CLOSE_YM = #{closeYm}
       AND C.CLOSE_STATUS = 'CLOSED'
       AND C.NODE_CD = '*'


    WITH RECURSIVE anc AS (
        SELECT N.NODE_CD, N.PARENT_NODE_CD
          FROM TB_SITE_NODE N
         WHERE N.CMPNY_CD = #{cmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
        UNION ALL
        SELECT P.NODE_CD, P.PARENT_NODE_CD
          FROM TB_SITE_NODE P
          JOIN anc A2
            ON P.CMPNY_CD = #{cmpnyCd} AND P.SITE_CD = #{siteCd} AND P.NODE_CD = A2.PARENT_NODE_CD
    )
    SELECT COUNT(*)
      FROM TB_ATTD_CLOSE C
     WHERE C.CMPNY_CD = #{cmpnyCd}
       AND C.SITE_CD  = #{siteCd}
       AND C.CLOSE_YM = #{closeYm}
       AND C.CLOSE_STATUS = 'CLOSED'
       AND (
             C.NODE_CD = '*'
          OR C.NODE_CD = #{nodeCd}
          OR ( C.INC_SUB_YN = 'Y' AND C.NODE_CD IN (SELECT NODE_CD FROM anc WHERE NODE_CD <> #{nodeCd}) )
       )

/* AppAdminApprovalMapper.selectHistoryLeave */ SELECT DISTINCT R.REQ_ID AS reqId , R.REQ_TYPE AS reqType , R.USER_CD AS userCd , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'USER_NM', R.USER_CD, null) AS requesterUserNm , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'NODE', R.SITE_CD, COALESCE(R.NODE_CD, U.NODE_CD)) AS nodeNm , R.WORK_YMD AS workYmd , DATE_FORMAT(R.INSERT_DATE, '%Y-%m-%dT%H:%i:%s') AS reqDate , DATE_FORMAT(R.PROCESS_DATE, '%Y-%m-%dT%H:%i:%s') AS processDate , R.REQ_STATUS AS reqStatus , R.PROCESS_USER_CD AS processUserCd , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'USER_NM', R.PROCESS_USER_CD, null) AS processUserNm , R.PROCESS_COMMENT AS rejectReason FROM TB_USER_ATTD_REQ R JOIN TB_USER_ATTD_REQ_APPROVAL AP ON AP.CMPNY_CD = R.CMPNY_CD AND AP.REQ_ID = R.REQ_ID AND AP.APPROVER_USER_CD = #{approverUserCd} LEFT JOIN TB_USER U ON U.CMPNY_CD = R.CMPNY_CD AND U.USER_CD = R.USER_CD WHERE R.CMPNY_CD = #{cmpnyCd} AND R.REQ_TYPE IN ('05', '06') AND R.REQ_STATUS IN ('02', '03', '04') AND R.DEL_YN = 'N'
AND R.WORK_YMD >= #{startYmd}
AND R.WORK_YMD <= #{endYmd}
AND ( R.USER_CD LIKE CONCAT('%', #{keyword}, '%') OR FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'USER_NM', R.USER_CD, null) LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY R.PROCESS_DATE DESC LIMIT #{limit} OFFSET #{offset}

/* AppAdminApprovalMapper.countHistoryLeave */
SELECT COUNT(DISTINCT R.REQ_ID)
  FROM TB_USER_ATTD_REQ R
  JOIN TB_USER_ATTD_REQ_APPROVAL AP
    ON AP.CMPNY_CD = R.CMPNY_CD
   AND AP.REQ_ID   = R.REQ_ID
   AND AP.APPROVER_USER_CD = #{approverUserCd}
 WHERE R.CMPNY_CD  = #{cmpnyCd}
   AND R.REQ_TYPE IN ('05', '06')
   AND R.REQ_STATUS IN ('02', '03', '04')
   AND R.DEL_YN     = 'N'

   AND R.WORK_YMD >= #{startYmd}


   AND R.WORK_YMD <= #{endYmd}


   AND (
         R.USER_CD LIKE CONCAT('%', #{keyword}, '%')
      OR FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'USER_NM', R.USER_CD, null) LIKE CONCAT('%', #{keyword}, '%')
   )

mapper.update:
/* AppAdminApprovalMapper.backfillReqNodeCd */
UPDATE TB_USER_ATTD_REQ
   SET NODE_CD     = #{nodeCd}
     , UPDATE_NO   = #{updateNo}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND REQ_ID   = #{reqId}
   AND NODE_CD IS NULL
   AND DEL_YN   = 'N'
